import React, { useState } from "react";
import { MpaIcon } from "../icon/MpaIcon";
import { MpaLogo } from "../logo/MpaLogo";
import { SvgMpaIcon, SvgMpaLogo } from "../../assets/icons/index";
import { NumberBadge } from "../numberBadge/index";
import "./SideNav.scss";
import { Link as RouterLink } from "react-router-dom"

type MenuItemType = {
  label: string;
  link?: string;
  menuItems?: MenuItemType[];
  subMenuItems?: MenuItemType[];
  leadingIcon?:  keyof typeof SvgMpaIcon | string;
  disabled?: boolean;
  badge?: number;
  onClick?: () => void;
};

export interface SideNavProps {
  id: string;
  logoUrl?: keyof typeof SvgMpaLogo | string;
  navItems?: MenuItemType[];
  colour?: "primary" | "secondary" | "tertiary";
  LinkComponent?: React.ComponentType<any>;
}

const SideNav: React.FC<SideNavProps> = ({ id, logoUrl, navItems, colour = "primary", LinkComponent }) => {


  const [openItems, setOpenItems] = useState<Set<string>>(new Set());
  const [isHovered, setIsHovered] = useState<boolean>(false);
  const toggleDropdown = (key: string, parentKey?: string) => {
    setOpenItems((prev) => {
      const newOpenItems = new Set(prev);
      if (newOpenItems.has(key)) {
        newOpenItems.delete(key);
      } else {
        if (!parentKey) {
          newOpenItems.clear();
        } else {
          [...newOpenItems].forEach((openKey) => {
            if (openKey.startsWith(parentKey) && openKey !== key) {
              newOpenItems.delete(openKey);
            }
          });
        }

        if (parentKey) {
          newOpenItems.add(parentKey);
        }

        newOpenItems.add(key);
      }
      return newOpenItems;
    });
  };

  const handleMouseEnter = () => {
    setIsHovered(true);
  };

  const handleMouseLeave = () => {
    setIsHovered(false);
  };

  const isSvgKey = (value: any): value is keyof typeof SvgMpaLogo => {
    return value in SvgMpaLogo;
  };

  const Link = LinkComponent ?? RouterLink

  const renderMenuItem = (item: MenuItemType, index: number, depth: number = 0, parentKey: string = "") => {
    const itemKey = parentKey ? `${parentKey}-${index}` : `${depth}-${index}`;
    const isOpen = openItems.has(itemKey);
    const depthClass = `side-depth-${depth}`;
    const badgeId = `${depth}-${index}`;

    return (
      <div
        key={itemKey}
        style={{ paddingTop: ".25em" }}
      >
        <div
          tabIndex={0}
          role="button"
          onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") toggleDropdown(itemKey, parentKey); }}
          className={`side-nav-menu-item 
            ${colour} 
            ${isOpen && isHovered ? "svmi-selected" : "svmi-default"} 
            ${item?.disabled ? "disabled" : ""} 
            ${depthClass}`}
          onClick={() => toggleDropdown(itemKey, parentKey)}
        >

          {item?.badge !== undefined && item?.badge > 0 && (
            <NumberBadge className="side-nav-menu-item-dot-badge" id={badgeId} type="dot" colour="error" />
          )}

          {item.leadingIcon && (
            <span className={`side-leading-icon ${colour} ${isOpen && !isHovered ? "svmi-selected" : "svmi-default"}`}>
              <MpaIcon iconName={item.leadingIcon} />
            </span>
          )}
          
            <Link to={item.link ?? "#"}>
              {item.label}
            </Link>

          {item?.badge !== undefined && item?.badge > 0 && (
            <div className="svmi-badgeMain">
              <NumberBadge id={badgeId} label={item.badge} type="counter" colour="error" />
            </div>
          )}

          {(item.menuItems || item.subMenuItems) && (
            <span className={`sidenav-chevron-icon ${isOpen ? "rotated" : ""}`}>
              <MpaIcon iconName={'ChevronRight'} size={20} />
            </span>
          )}
        </div>

        {isOpen && isHovered && (item.menuItems || item.subMenuItems) && (
          <div className="side-nav-submenu-item">
            {item.menuItems?.map((subItem, subIndex) =>
              renderMenuItem(subItem, subIndex, depth + 1, itemKey)
            )}
            {item.subMenuItems?.map((subItem, subIndex) =>
              renderSubMenuItem(subItem, subIndex, depth + 1, itemKey)
            )}
          </div>
        )}
      </div>
    );
  };

  const renderSubMenuItem = (item: MenuItemType, index: number, depth: number = 0, parentKey: string = "") => {
    const itemKey = parentKey ? `${parentKey}-${index}` : `${depth}-${index}`;
    const depthClass = `side-depth-${depth}`;

    return (
      <div
        key={itemKey}
        style={{ paddingTop: ".25em" }}
      >
        <div
          tabIndex={0}
          role="button"
          className={`side-nav-menu-item 
            ${colour} 
            svmi-default
            ${item?.disabled ? "disabled" : ""} 
            ${depthClass}`}
        >
          
            <Link to={item.link ?? "#"} onClick={item.onClick}>
              {item.label}
            </Link>
          

        </div>
      </div>
    );
  };

  return (
    <div id={id} className="sidenav"
      tabIndex={0}
      role="button"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <div className="logo-container">
        {isSvgKey(logoUrl) ?
          <MpaLogo logoName={logoUrl} />
          :
          <img src={logoUrl} alt="Logo" width={'100%'} height={'100%'}></img>
        }

      </div>

      <div className={`side-nav-menu`}>
        {navItems?.map((item, index) => renderMenuItem(item, index, 0))}
      </div>
    </div>
  );
};

export default SideNav;
